const b = $input.first().json.body || $input.first().json;
const clean = v => (v === undefined || v === null) ? '' : String(v).trim();

const email = clean(b.email).toLowerCase();

let first = clean(b.firstName), last = clean(b.lastName);
if (!first) {
  const parts = clean(b.name).split(/\s+/).filter(Boolean);
  first = parts.shift() || '';
  last = parts.join(' ');
}

const rawPhone = clean(b.phone);
const d = rawPhone.replace(/\D/g, '').replace(/^1(?=\d{10}$)/, '');
const phone = d.length === 10 ? '(' + d.slice(0,3) + ')' + d.slice(3,6) + '-' + d.slice(6) : rawPhone;

const formName = clean(b.source);
const searched = clean(b.searchedAddress);
let leadType = 'General';
if (/valuation|sell/i.test(formName) || searched) leadType = 'Seller';
if (/buyer|buy/i.test(formName) || /buyer/i.test(clean(b.formName))) leadType = 'Buyer';

const utmSource = clean(b.utm_source);
const metaLeadId = clean(b.leadgenId || b.leadId);
let origin;
if (metaLeadId) origin = 'Meta Instant Form';
else if (utmSource) origin = 'Paid ad: ' + utmSource;
else if (clean(b.referrer)) origin = 'Referral: ' + clean(b.referrer);
else origin = 'Website (organic/direct)';


let sourceLabel;
if (metaLeadId) {
  const fn = formName.toLowerCase();
  sourceLabel = 'Meta lead ad' + (fn.includes('variant a') ? ' (house listing)' : fn.includes('variant b') ? ' (headshot)' : (formName ? ' - ' + formName : ''));
} else if (/valuation|sell/i.test(formName) || searched) {
  sourceLabel = 'Home valuation' + (searched ? ' - ' + searched : '');
} else if (utmSource) {
  sourceLabel = 'Paid ad: ' + (clean(b.utm_content) || utmSource);
} else if (clean(b.referrer)) {
  sourceLabel = 'Referral: ' + clean(b.referrer);
} else {
  sourceLabel = 'Website contact';
}

return [{ json: {
  timestamp: DateTime.now().setZone('America/Chicago').toFormat('yyyy-LL-dd HH:mm'),
  first, last, email, phone, leadType, origin, sourceLabel,
  campaign: clean(b.utm_campaign),
  ad: clean(b.utm_content),
  searchedAddress: searched,
  message: clean(b.message),
  metaLeadId,
    priceRange: clean(b.priceRange),
    timeline: clean(b.timeline),
    financing: clean(b.financing),
  onMailerList: (b.newsletterOptIn === true || clean(b.newsletterOptIn).toLowerCase() === 'true') ? 'Y' : '',
  formName
} }];

const lead = $('Normalize Lead').first().json;
const rows = $input.all().map(i => i.json);

const norm = s => String(s || '').trim().toLowerCase();
const digits = s => String(s || '').replace(/\D/g, '').replace(/^1(?=\d{10}$)/, '');
const leadPhone = digits(lead.phone);

let match = null;
for (const r of rows) {
  if (lead.email && norm(r['Email']) === norm(lead.email)) { match = r; break; }
  if (!match && leadPhone.length === 10 && digits(r['Phone']) === leadPhone) { match = r; }
}

const notes = match
  ? ('Already in Database as ' + [match['First Name'], match['Last Name']].filter(Boolean).join(' ')
     + ' (' + (match['Category'] || 'uncategorized') + ')').trim()
  : '';

return [{ json: { ...lead, alreadyInDatabase: match ? 'Y' : '', notes } }];

const lead = $('Check For Duplicate').first().json;

// E.164 the phone; anything that isn't a clean 10-digit US number is skipped
const d = String(lead.phone || '').replace(/\D/g, '').replace(/^1(?=\d{10}$)/, '');
const to = d.length === 10 ? '+1' + d : '';

// TCPA: no marketing texts outside 8am-9pm local. Central is Hector's market.
const hour = DateTime.now().setZone('America/Chicago').hour;
const quiet = hour < 8 || hour >= 21;

const first = (lead.first || '').trim() || 'there';
const addr  = String(lead.searchedAddress || '').split(',')[0].trim();

const body = addr
  ? `Hey ${first}, it's Hector. Thanks for reaching out about ${addr}. Before I put a number together I'd like to hear a little about the home from you, so I'll give you a call in a bit. If another time is easier, just text me back and let me know.\n\nReply STOP to unsubscribe.`
  : `Hey ${first}, it's Hector. Thanks for reaching out. I'll give you a call in a bit to hear more about what you're looking for and how I can help.\n\nReply STOP to unsubscribe.`;

const metaBody = "Hey " + first + ", it's Hector. Saw you filled out my form about homes here in Dallas. I'll give you a call in a bit to hear more about what you're looking for and how I can help.\n\nReply STOP to unsubscribe.";
const isMeta = String(lead.origin || "").indexOf("Meta Instant Form") === 0;
const finalBody = isMeta ? metaBody : body;

const quietBody = `Hey ${first}, it's Hector. Thanks for reaching out, I got your info. Won't bug you this late, but I'll give you a call in the morning. Talk soon.\n\nReply STOP to unsubscribe.`;

const send = Boolean(to);

return [{ json: {
  to, body: quiet ? quietBody : finalBody, send,
  skipReason: !to ? 'no valid US mobile' : '',
  email: lead.email,
} }];

