  if (s.indexOf('<test lead') === 0) return s;
  s = s.replace(/_/g, ' ').replace(/\s+/g, ' ').trim();
  s = s.replace(/\$(\d+(?:\.\d+)?)\s*([km])\b/gi, function(m, n, u){ return '$' + n + u.toUpperCase(); });
  return s.charAt(0).toUpperCase() + s.slice(1);
}

